/**
 * DNS records a custom domain needs, and a live checker over DNS-over-HTTPS.
 *
 * Source: developers.cloudflare.com/email-service/configuration/domains/ (checked 2026-11).
 * Email Routing (receiving) and Email Sending use separate records:
 *
 *   receiving  MX   <domain>                      route1/2/3.mx.cloudflare.net (priorities chosen by Cloudflare)
 *              TXT  <domain>                      v=spf1 include:_spf.mx.cloudflare.net ~all  (merge into an existing SPF)
 *              TXT  cf2024-1._domainkey.<domain>  v=DKIM1; ... (key generated by Cloudflare)
 *   sending    MX   cf-bounce.<domain>            route1/2/3.mx.cloudflare.net
 *              TXT  cf-bounce.<domain>            v=spf1 include:_spf.mx.cloudflare.net ~all
 *              TXT  cf-bounce._domainkey.<domain> v=DKIM1; ... (key generated by Cloudflare)
 *              TXT  _dmarc.<domain>               v=DMARC1; p=none  (any valid policy passes)
 *
 * Both services require the zone to use Cloudflare DNS. The DKIM keys only exist once the domain
 * is onboarded, so those records are checked for presence (`v=DKIM1` with a key), not content.
 *
 * Before any of that counts, the account proves it controls the domain:
 *
 *   ownership  TXT  _afs-verify.<domain>          afs-verify=<token>  (per account; see src/service/domains.ts)
 */

export type RecordPurpose = "ownership" | "receiving" | "sending";
export type RecordMatch = "txt_exact" | "mx_host" | "spf_include" | "dkim_present" | "dmarc_present";

export interface DnsRecord {
  id: string;
  purpose: RecordPurpose;
  type: "MX" | "TXT";
  /** Fully-qualified name. */
  name: string;
  /** Name relative to the domain ("@" for the apex), as most DNS UIs want it. */
  host: string;
  value: string;
  priority: number | null;
  match: RecordMatch;
  note?: string;
}

export const CF_MX_HOSTS = ["route1.mx.cloudflare.net", "route2.mx.cloudflare.net", "route3.mx.cloudflare.net"];
export const CF_SPF_INCLUDE = "include:_spf.mx.cloudflare.net";
export const CF_SPF = `v=spf1 ${CF_SPF_INCLUDE} ~all`;
export const ROUTING_DKIM_SELECTOR = "cf2024-1";
export const SENDING_SUBDOMAIN = "cf-bounce";
export const DEFAULT_DMARC = "v=DMARC1; p=none";
export const CHALLENGE_LABEL = "_afs-verify";
export const CHALLENGE_PREFIX = "afs-verify=";

function rel(name: string, domain: string): string {
  if (name === domain) return "@";
  return name.endsWith(`.${domain}`) ? name.slice(0, -domain.length - 1) : name;
}

export function buildDomainRecords(domain: string): DnsRecord[] {
  const d = domain.toLowerCase();
  const bounce = `${SENDING_SUBDOMAIN}.${d}`;
  const rec = (r: Omit<DnsRecord, "host">): DnsRecord => ({ ...r, host: rel(r.name, d) });
  const mxNote = "Priority is assigned by Cloudflare when Email Routing / Email Sending is enabled; any priority passes the check.";
  return [
    ...CF_MX_HOSTS.map((h, i) =>
      rec({
        id: `receiving_mx_${i + 1}`,
        purpose: "receiving",
        type: "MX",
        name: d,
        value: h,
        priority: null,
        match: "mx_host",
        note: i === 0 ? `${mxNote} Remove MX records of other providers: Email Routing cannot share the domain.` : mxNote,
      }),
    ),
    rec({
      id: "receiving_spf",
      purpose: "receiving",
      type: "TXT",
      name: d,
      value: CF_SPF,
      priority: null,
      match: "spf_include",
      note: "If the domain already has an SPF record, add include:_spf.mx.cloudflare.net to it instead of adding a second one.",
    }),
    rec({
      id: "receiving_dkim",
      purpose: "receiving",
      type: "TXT",
      name: `${ROUTING_DKIM_SELECTOR}._domainkey.${d}`,
      value: "v=DKIM1; h=sha256; k=rsa; p=<public key generated by Cloudflare>",
      priority: null,
      match: "dkim_present",
      note: "Created by Cloudflare when Email Routing is enabled on the zone.",
    }),
    ...CF_MX_HOSTS.map((h, i) =>
      rec({
        id: `sending_mx_${i + 1}`,
        purpose: "sending",
        type: "MX",
        name: bounce,
        value: h,
        priority: null,
        match: "mx_host",
        note: mxNote,
      }),
    ),
    rec({ id: "sending_spf", purpose: "sending", type: "TXT", name: bounce, value: CF_SPF, priority: null, match: "spf_include" }),
    rec({
      id: "sending_dkim",
      purpose: "sending",
      type: "TXT",
      name: `${SENDING_SUBDOMAIN}._domainkey.${d}`,
      value: "v=DKIM1; h=sha256; k=rsa; p=<public key generated by Cloudflare>",
      priority: null,
      match: "dkim_present",
      note: "Created by Cloudflare when the domain is onboarded to Email Sending.",
    }),
    rec({
      id: "sending_dmarc",
      purpose: "sending",
      type: "TXT",
      name: `_dmarc.${d}`,
      value: DEFAULT_DMARC,
      priority: null,
      match: "dmarc_present",
      note: "Any valid DMARC policy passes. Start with p=none; tighten to quarantine/reject once mail flows.",
    }),
  ];
}

/** The ownership challenge record: TXT _afs-verify.<domain> "afs-verify=<token>". Pure. */
export function ownershipRecord(domain: string, token: string): DnsRecord {
  const d = domain.toLowerCase();
  return {
    id: "ownership_txt",
    purpose: "ownership",
    type: "TXT",
    name: `${CHALLENGE_LABEL}.${d}`,
    host: CHALLENGE_LABEL,
    value: `${CHALLENGE_PREFIX}${token}`,
    priority: null,
    match: "txt_exact",
    note: "Proves this account controls the domain. Until verify finds it, the domain receives no mail, cannot send and gets no inboxes, and another account may claim it. The value is fixed for your account; you may remove the record once ownership is verified.",
  };
}

/**
 * Replace placeholder values with the exact records Cloudflare returned (auto_configure reads
 * GET /zones/:zone/email/routing/dns and the sending-subdomain DNS endpoint).
 */
export function mergeCloudflareRecords(
  records: DnsRecord[],
  cf: { type?: string; name?: string; content?: string; priority?: number }[],
): DnsRecord[] {
  return records.map((r) => {
    const hit = cf.find((c) => {
      if ((c.type ?? "").toUpperCase() !== r.type || (c.name ?? "").toLowerCase().replace(/\.$/, "") !== r.name) return false;
      const content = (c.content ?? "").toLowerCase().replace(/\.$/, "").replace(/^"|"$/g, "");
      if (r.match === "mx_host") return content === r.value;
      if (r.match === "dkim_present") return content.startsWith("v=dkim1");
      if (r.match === "spf_include") return content.startsWith("v=spf1");
      return content.startsWith("v=dmarc1");
    });
    if (!hit) return r;
    return {
      ...r,
      value: (hit.content ?? r.value).replace(/^"|"$/g, ""),
      priority: hit.type?.toUpperCase() === "MX" ? (hit.priority ?? r.priority) : r.priority,
    };
  });
}

// ---------------------------------------------------------------------------------------------
// DNS-over-HTTPS (application/dns-json) at cloudflare-dns.com

export interface DohResponse {
  Status: number;
  Answer?: { name: string; type: number; TTL: number; data: string }[];
}

const TYPE_CODES: Record<string, number> = { MX: 15, TXT: 16, CNAME: 5 };

/** Normalise one DoH answer: MX "13 route1.mx.cloudflare.net." -> host; TXT '"a" "b"' -> "ab". */
export function parseDohData(type: "MX" | "TXT", data: string): { value: string; priority: number | null } {
  if (type === "MX") {
    const m = /^\s*(\d+)\s+(\S+)\s*$/.exec(data);
    if (m) return { value: m[2]!.toLowerCase().replace(/\.$/, ""), priority: Number(m[1]) };
    return { value: data.trim().toLowerCase().replace(/\.$/, ""), priority: null };
  }
  const parts = [...data.matchAll(/"((?:[^"\\]|\\.)*)"/g)].map((m) => m[1]!.replace(/\\(.)/g, "$1"));
  return { value: parts.length ? parts.join("") : data.trim(), priority: null };
}

export interface RecordCheck {
  id: string;
  purpose: RecordPurpose;
  type: "MX" | "TXT";
  name: string;
  expected: string;
  status: "pass" | "fail";
  found: string[];
  fix?: string;
}

export function evaluateRecord(record: DnsRecord, found: string[]): RecordCheck {
  const base = { id: record.id, purpose: record.purpose, type: record.type, name: record.name, expected: record.value, found };
  const lower = found.map((f) => f.toLowerCase());
  switch (record.match) {
    case "txt_exact": {
      if (found.some((f) => f.trim() === record.value)) return { ...base, status: "pass" };
      return {
        ...base,
        status: "fail",
        fix: `Add TXT ${record.host} "${record.value}" (full name ${record.name}). It proves you control the domain.`,
      };
    }
    case "mx_host": {
      if (lower.includes(record.value)) return { ...base, status: "pass" };
      const foreign = lower.filter((v) => !CF_MX_HOSTS.includes(v));
      const fix = foreign.length
        ? `Remove the MX records pointing to ${foreign.join(", ")} and enable Email ${record.purpose === "receiving" ? "Routing" : "Sending"} for ${record.name} in Cloudflare; it adds ${record.value}.`
        : `Add MX ${record.host} -> ${record.value} (or enable Email ${record.purpose === "receiving" ? "Routing" : "Sending"} in the Cloudflare dashboard, which adds it).`;
      return { ...base, status: "fail", fix };
    }
    case "spf_include": {
      const spf = lower.filter((v) => v.startsWith("v=spf1"));
      if (spf.length === 1 && spf[0]!.split(/\s+/).includes(CF_SPF_INCLUDE)) return { ...base, status: "pass" };
      if (spf.length > 1)
        return {
          ...base,
          status: "fail",
          fix: `${record.name} has ${spf.length} SPF records; merge them into one that includes ${CF_SPF_INCLUDE}.`,
        };
      if (spf.length === 1)
        return {
          ...base,
          status: "fail",
          fix: `Add ${CF_SPF_INCLUDE} to the existing SPF record at ${record.name} (before the ~all/-all).`,
        };
      return { ...base, status: "fail", fix: `Add TXT ${record.host} "${CF_SPF}".` };
    }
    case "dkim_present": {
      if (lower.some((v) => v.startsWith("v=dkim1") && /p=[a-z0-9+/]{20,}/i.test(v))) return { ...base, status: "pass" };
      return {
        ...base,
        status: "fail",
        fix:
          record.purpose === "receiving"
            ? `Enable Email Routing for the zone in Cloudflare (Compute > Email Service > Email Routing); it publishes ${record.name}.`
            : `Onboard the domain to Email Sending in Cloudflare (Compute > Email Service > Email Sending > Onboard Domain); it publishes ${record.name}.`,
      };
    }
    case "dmarc_present": {
      const d = lower.filter((v) => v.startsWith("v=dmarc1"));
      if (d.length === 1 && /\bp=(none|quarantine|reject)\b/.test(d[0]!)) return { ...base, status: "pass" };
      if (d.length > 1) return { ...base, status: "fail", fix: `${record.name} has ${d.length} DMARC records; keep exactly one.` };
      return { ...base, status: "fail", fix: `Add TXT ${record.host} "${DEFAULT_DMARC}".` };
    }
  }
}

export type Fetcher = (input: string, init?: RequestInit) => Promise<Response>;

export async function dohQuery(name: string, type: "MX" | "TXT", fetcher: Fetcher = fetch): Promise<string[]> {
  const url = `https://cloudflare-dns.com/dns-query?name=${encodeURIComponent(name)}&type=${type}`;
  const res = await fetcher(url, { headers: { accept: "application/dns-json" } });
  if (!res.ok) throw new Error(`DoH ${type} ${name}: HTTP ${res.status}`);
  const body = (await res.json()) as DohResponse;
  // Status 3 = NXDOMAIN; anything but 0 means no usable answer.
  if (body.Status !== 0) return [];
  return (body.Answer ?? []).filter((a) => a.type === TYPE_CODES[type]).map((a) => parseDohData(type, a.data).value);
}

export interface DomainCheck {
  domain: string;
  checked_at: number;
  /** "pass" also when no ownership record was checked (ownership already proven). */
  ownership: "pass" | "fail";
  /** "disabled" for a send-only domain (receiving: false). */
  receiving: "pass" | "fail" | "disabled";
  sending: "pass" | "fail";
  records: RecordCheck[];
  next_steps: string[];
}

export async function checkDomainDns(
  domain: string,
  records: DnsRecord[],
  fetcher: Fetcher = fetch,
  now = Date.now(),
  opts: { receiving?: boolean } = {},
): Promise<DomainCheck> {
  const keys = [...new Set(records.map((r) => `${r.type} ${r.name}`))];
  const answers = new Map<string, string[] | Error>();
  await Promise.all(
    keys.map(async (k) => {
      const [type, name] = k.split(" ") as ["MX" | "TXT", string];
      try {
        answers.set(k, await dohQuery(name, type, fetcher));
      } catch (e) {
        answers.set(k, e instanceof Error ? e : new Error(String(e)));
      }
    }),
  );
  const checks = records.map((r) => {
    const a = answers.get(`${r.type} ${r.name}`);
    if (a instanceof Error) {
      return {
        id: r.id,
        purpose: r.purpose,
        type: r.type,
        name: r.name,
        expected: r.value,
        status: "fail" as const,
        found: [],
        fix: `DNS lookup failed (${a.message}); retry verify in a minute.`,
      };
    }
    return evaluateRecord(r, a ?? []);
  });
  return summarise(domain, checks, now, opts);
}

export function summarise(domain: string, checks: RecordCheck[], now = Date.now(), opts: { receiving?: boolean } = {}): DomainCheck {
  const ok = (p: RecordPurpose) => (checks.filter((c) => c.purpose === p).every((c) => c.status === "pass") ? "pass" : "fail");
  const ownership = ok("ownership");
  const sendOnly = opts.receiving === false;
  const receiving = sendOnly ? ("disabled" as const) : ok("receiving");
  const sending = ok("sending");
  const next: string[] = [];
  for (const c of checks) if (c.status === "fail" && c.fix && !next.includes(c.fix)) next.push(c.fix);
  if (receiving === "pass") {
    next.push(
      `Make sure the zone's Email Routing catch-all rule (it lives on the zone apex and also covers routing subdomains without a literal rule) is "Send to a Worker" -> this Worker (the operator can run auto_configure).`,
    );
  }
  if (ownership === "pass" && receiving !== "fail" && sending === "pass")
    next.unshift(
      sendOnly
        ? `All DNS records pass. ${domain} is send-only: create an inbox on it (POST /v1/inboxes {"username":...,"domain":"${domain}"}) to send from; its mail keeps going to your existing MX.`
        : 'All DNS records pass. Create inboxes on this domain with POST /v1/inboxes {"username":...,"domain":"' + domain + '"}.',
    );
  else next.push("DNS changes on Cloudflare usually propagate in 5-15 minutes; run verify again after fixing.");
  return { domain, checked_at: now, ownership, receiving, sending, records: checks, next_steps: next };
}

// ---------------------------------------------------------------------------------------------
// Zone file export

/** Default MX priorities for the zone file (Cloudflare assigns its own; any priority passes verify). */
const MX_PRIORITY = [10, 20, 30];

const quoteTxt = (v: string) => {
  // TXT strings are at most 255 bytes each: split long values (DKIM keys) into several strings.
  const parts: string[] = [];
  for (let i = 0; i < v.length; i += 250) parts.push(`"${v.slice(i, i + 250).replace(/(["\\])/g, "\\$1")}"`);
  return parts.join(" ");
};

/**
 * The records as a BIND zone-file fragment (RFC 1035 master file), relative to `$ORIGIN <domain>.`,
 * for DNS providers and tools that import zone files. Records whose value only exists once
 * Cloudflare generated it (DKIM keys before onboarding) are written as comments. Pure.
 */
export function zoneFile(domain: string, records: DnsRecord[], now = Date.now()): string {
  const d = domain.toLowerCase();
  const lines = [
    `; Email DNS records for ${d}, from AgentFirstStack Mail (${new Date(now).toISOString()}).`,
    "; Import into the zone, or add each record by hand. Then POST /v1/domains/" + d + "/verify.",
    `$ORIGIN ${d}.`,
    "$TTL 3600",
  ];
  const mxSeen = new Map<string, number>();
  for (const r of records) {
    const host = r.host === "@" ? "@" : r.host;
    lines.push(`; ${r.id} (${r.purpose})${r.note ? `: ${r.note.replace(/[\r\n]+/g, " ")}` : ""}`);
    if (r.type === "MX") {
      const i = mxSeen.get(r.name) ?? 0;
      mxSeen.set(r.name, i + 1);
      lines.push(`${host}\tIN\tMX\t${r.priority ?? MX_PRIORITY[i] ?? 30}\t${r.value}.`);
    } else if (r.value.includes("<")) {
      lines.push(`; ${host}\tIN\tTXT\t${quoteTxt(r.value)}  ; created by Cloudflare when the domain is onboarded`);
    } else lines.push(`${host}\tIN\tTXT\t${quoteTxt(r.value)}`);
  }
  return `${lines.join("\n")}\n`;
}
